/// CERT_LIMIT
pub fn cert_limit(num_players: u8) -> u8 {
    match num_players {
        3 => 21,
        4 => 15,
        5 => 12,
        _ => panic!("1822PNW: invalid player count {num_players}"),
    }
}

/// STARTING_CASH
pub fn starting_cash(num_players: u8) -> i32 {
    match num_players {
        3 => 500,
        4 => 375,
        5 => 300,
        _ => panic!("1822PNW: invalid player count {num_players}"),
    }
}

/// BIDDING_TOKENS (keyed by player count)
pub fn bidding_tokens(players: usize) -> i32 {
    match players {
        3 => 5,
        4 => 4,
        5 => 4,
        _ => 0,
    }
}

